-- M80 synthetic-only Scope 1 beta setup foundation. No calculation, release promotion, document or invitation path.
create table neuvetra.scope1_beta_release_records(
  id uuid primary key,
  profile_id text not null,
  status text not null check(status in('held_candidate','released','blocked','superseded')),
  method_id text not null,
  method_version text,
  method_sha256 text not null check(method_sha256~'^[0-9a-f]{64}$'),
  engine_sha256 text not null check(engine_sha256~'^[0-9a-f]{64}$'),
  factor_identity_sha256 text not null check(factor_identity_sha256~'^[0-9a-f]{64}$'),
  gwp_identity_sha256 text not null check(gwp_identity_sha256~'^[0-9a-f]{64}$'),
  source_artifact_ids jsonb not null check(jsonb_typeof(source_artifact_ids)='array'),
  reporting_period_start date not null,
  reporting_period_end_exclusive date not null,
  effective_at timestamptz,
  superseded_at timestamptz,
  exclusions jsonb not null check(jsonb_typeof(exclusions)='array'),
  decision_artifact_sha256 text not null check(decision_artifact_sha256~'^[0-9a-f]{64}$'),
  created_at timestamptz not null default clock_timestamp(),
  check(reporting_period_start='2025-01-01' and reporting_period_end_exclusive='2026-01-01'),
  check(status<>'held_candidate' or (effective_at is null and superseded_at is null))
);
create unique index scope1_beta_release_identity on neuvetra.scope1_beta_release_records(profile_id,status,method_sha256,engine_sha256,factor_identity_sha256,gwp_identity_sha256);

insert into neuvetra.scope1_beta_release_records(id,profile_id,status,method_id,method_version,method_sha256,engine_sha256,factor_identity_sha256,gwp_identity_sha256,source_artifact_ids,reporting_period_start,reporting_period_end_exclusive,exclusions,decision_artifact_sha256) values
