create table neuvetra.scope1_beta_fixture_admissions(
  company_id uuid not null references neuvetra.companies(id),
  fixture_profile_id text not null,
  fixture_version integer not null,
  fixture_sha256 text not null check(fixture_sha256~'^[0-9a-f]{64}$'),
  active boolean not null,
  admitted_by uuid not null references auth.users(id),
  admitted_at timestamptz not null default clock_timestamp(),
  primary key(company_id,fixture_profile_id,fixture_version,fixture_sha256),
  check(fixture_profile_id='m80-synthetic-scope1-foundation-v1' and fixture_version=1 and fixture_sha256='2c6a9f78cded2a209bf536969e4ea389baa7fe1633c8ef63fad0c22826f77dc1')
);
create unique index scope1_beta_one_active_admission on neuvetra.scope1_beta_fixture_admissions(company_id) where active;

create table neuvetra.scope1_beta_setup_heads(
  company_id uuid not null references neuvetra.companies(id),
  reporting_year integer not null check(reporting_year=2025),
  version_id uuid,
  revision integer not null default 0 check(revision>=0),
  primary key(company_id,reporting_year),
  unique(version_id,company_id)
);
create table neuvetra.scope1_beta_setup_versions(
  id uuid primary key,
  company_id uuid not null,
  reporting_year integer not null check(reporting_year=2025),
  revision integer not null check(revision>0),
  previous_version_id uuid,
  previous_version_sha256 text check(previous_version_sha256 is null or previous_version_sha256~'^[0-9a-f]{64}$'),
  fixture_profile_id text not null,
  fixture_version integer not null,
  fixture_sha256 text not null check(fixture_sha256~'^[0-9a-f]{64}$'),
  payload jsonb not null,
  canonical_payload text not null,
  payload_sha256 text not null check(payload_sha256~'^[0-9a-f]{64}$'),
  version_sha256 text not null check(version_sha256~'^[0-9a-f]{64}$'),
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null,
  correction_reason text check(correction_reason is null or correction_reason='synthetic_fact_correction'),
  data_classification text not null check(data_classification='synthetic_rehearsal'),
  completeness text not null check(completeness='incomplete'),
  released_supported_count integer not null check(released_supported_count=0),
  unique(id,company_id),
  unique(company_id,reporting_year,revision),
  unique(company_id,version_sha256),
  foreign key(company_id,fixture_profile_id,fixture_version,fixture_sha256) references neuvetra.scope1_beta_fixture_admissions(company_id,fixture_profile_id,fixture_version,fixture_sha256),
  foreign key(previous_version_id,company_id) references neuvetra.scope1_beta_setup_versions(id,company_id),
  check((revision=1 and previous_version_id is null and previous_version_sha256 is null and correction_reason is null) or (revision>1 and previous_version_id is not null and previous_version_sha256 is not null and correction_reason='synthetic_fact_correction'))
);
alter table neuvetra.scope1_beta_setup_heads add foreign key(version_id,company_id) references neuvetra.scope1_beta_setup_versions(id,company_id);

create table neuvetra.scope1_beta_requests(
  company_id uuid not null references neuvetra.companies(id),
  idempotency_key uuid not null,
  actor_id uuid not null references auth.users(id),
  request_sha256 text not null check(request_sha256~'^[0-9a-f]{64}$'),
  record_id uuid not null,
  created_at timestamptz not null,
  primary key(company_id,idempotency_key),
  foreign key(record_id,company_id) references neuvetra.scope1_beta_setup_versions(id,company_id)
);
create table neuvetra.scope1_beta_audit(
  sequence bigserial primary key,
  id uuid not null unique,
  company_id uuid not null references neuvetra.companies(id),
  record_id uuid not null,
  event_type text not null check(event_type='setup_saved'),
  record_sha256 text not null check(record_sha256~'^[0-9a-f]{64}$'),
  actor_id uuid not null references auth.users(id),
  created_at timestamptz not null,
  unique(company_id,event_type,record_id),
  foreign key(record_id,company_id) references neuvetra.scope1_beta_setup_versions(id,company_id)
);

do $$declare t text;begin
  foreach t in array array['scope1_beta_release_records','scope1_beta_fixture_admissions','scope1_beta_setup_heads','scope1_beta_setup_versions','scope1_beta_requests','scope1_beta_audit'] loop
    execute format('alter table neuvetra.%I enable row level security',t);
    execute format('alter table neuvetra.%I force row level security',t);
    execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);
  end loop;
end $$;
create policy m80_release_read on neuvetra.scope1_beta_release_records for select to neuvetra_runtime using(neuvetra.has_staging_access());
create policy m80_admission_read on neuvetra.scope1_beta_fixture_admissions for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id));
create policy m80_head_read on neuvetra.scope1_beta_setup_heads for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id));
create policy m80_version_read on neuvetra.scope1_beta_setup_versions for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id));
create policy m80_request_read on neuvetra.scope1_beta_requests for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id));
create policy m80_audit_read on neuvetra.scope1_beta_audit for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id));
grant select on neuvetra.scope1_beta_release_records,neuvetra.scope1_beta_fixture_admissions,neuvetra.scope1_beta_setup_heads,neuvetra.scope1_beta_setup_versions,neuvetra.scope1_beta_requests,neuvetra.scope1_beta_audit to neuvetra_runtime;
revoke all on sequence neuvetra.scope1_beta_audit_sequence_seq from public,authenticated,neuvetra_runtime;

create trigger scope1_beta_release_immutable before update or delete on neuvetra.scope1_beta_release_records for each row execute function neuvetra.reject_inventory_history_mutation();
create trigger scope1_beta_version_immutable before update or delete on neuvetra.scope1_beta_setup_versions for each row execute function neuvetra.reject_inventory_history_mutation();
create trigger scope1_beta_request_immutable before update or delete on neuvetra.scope1_beta_requests for each row execute function neuvetra.reject_inventory_history_mutation();
create trigger scope1_beta_audit_immutable before update or delete on neuvetra.scope1_beta_audit for each row execute function neuvetra.reject_inventory_history_mutation();

create function neuvetra.m80_assert_setup(target_company uuid,s jsonb) returns void language plpgsql set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare x jsonb;y jsonb;expected_sources jsonb;expected_evidence jsonb;begin
  perform neuvetra.m71_keys(s,'companyId,dataClassification,reportingPeriod,consolidationApproach,boundaryProposal,entities,locations,sources,evidenceRequirements,completeness');
  if s->>'companyId'is distinct from target_company::text or s->>'dataClassification'is distinct from 'synthetic_rehearsal' or s->'reportingPeriod'is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or s->>'consolidationApproach'is distinct from 'operational_control_proposed' or s->>'completeness'is distinct from 'incomplete' or octet_length(convert_to(neuvetra.m67_canonical(s),'utf8'))>50000 then raise exception 'invalid synthetic setup' using errcode='22023';end if;
  perform neuvetra.m71_keys(s->'boundaryProposal','reportingYearState,jointVentureState,ownershipChangeState');
  if s#>>'{boundaryProposal,reportingYearState}'is distinct from 'calendar_2025_proposed' or coalesce(s#>>'{boundaryProposal,jointVentureState}','')not in('unknown','none_proposed') or coalesce(s#>>'{boundaryProposal,ownershipChangeState}','')not in('unknown','none_proposed') then raise exception 'invalid synthetic boundary' using errcode='22023';end if;
  if jsonb_array_length(s->'entities')<>1 or jsonb_array_length(s->'locations')<>2 or jsonb_array_length(s->'sources')<>14 or jsonb_array_length(s->'evidenceRequirements')<>19 then raise exception 'fixed fixture census required' using errcode='22023';end if;
  for x in select value from jsonb_array_elements(s->'entities') loop perform neuvetra.m71_keys(x,'entityId,ownershipState,controlState,activePeriodState,inclusionState');if x->>'entityId'is distinct from '80000000-0000-4000-8000-000000000001' or coalesce(x->>'ownershipState','')not in('unknown','wholly_owned_proposed','other_structure_proposed') or coalesce(x->>'controlState','')not in('unknown','operational_control_proposed','not_controlled_proposed') or coalesce(x->>'activePeriodState','')not in('unknown','full_2025_proposed','partial_or_changed') or coalesce(x->>'inclusionState','')not in('unknown','included_proposed','excluded_proposed') then raise exception 'invalid synthetic entity' using errcode='22023';end if;end loop;
  if (select array_agg(x->>'locationId'order by x->>'locationId'collate "C")from jsonb_array_elements(s->'locations')x)is distinct from array['80000000-0000-4000-8000-000000000101','80000000-0000-4000-8000-000000000102'] then raise exception 'fixed fixture locations required'using errcode='22023';end if;
  for x in select value from jsonb_array_elements(s->'locations') loop perform neuvetra.m71_keys(x,'locationId,entityId,countryCode,regionCode,controlState,activePeriodState,inclusionState');if x->>'entityId'is distinct from '80000000-0000-4000-8000-000000000001' or coalesce(x->>'locationId','')not in('80000000-0000-4000-8000-000000000101','80000000-0000-4000-8000-000000000102') or coalesce(x->>'countryCode','')not in('US','unknown') or coalesce(x->>'regionCode','')not in('CA','other_us','unknown') or coalesce(x->>'controlState','')not in('unknown','operational_control_proposed','not_controlled_proposed') or coalesce(x->>'activePeriodState','')not in('unknown','full_2025_proposed','partial_or_changed') or coalesce(x->>'inclusionState','')not in('unknown','included_proposed','excluded_proposed') then raise exception 'invalid synthetic location' using errcode='22023';end if;end loop;
  expected_sources:='[{"sourceId":"80000000-0000-4000-8000-000000001001","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000101","category":"stationary_combustion","subtype":"natural_gas"},{"sourceId":"80000000-0000-4000-8000-000000001002","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000101","category":"stationary_combustion","subtype":"distillate_no2"},{"sourceId":"80000000-0000-4000-8000-000000001003","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000102","category":"mobile_combustion","subtype":"on_road_vehicle"},{"sourceId":"80000000-0000-4000-8000-000000001004","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000101","category":"fugitive","subtype":"refrigeration"},{"sourceId":"80000000-0000-4000-8000-000000001005","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000101","category":"fugitive","subtype":"fixed_hvac"},{"sourceId":"80000000-0000-4000-8000-000000001006","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000102","category":"fugitive","subtype":"fire_suppression"},{"sourceId":"80000000-0000-4000-8000-000000001007","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000102","category":"fugitive","subtype":"refrigeration"},{"sourceId":"80000000-0000-4000-8000-000000001008","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000102","category":"fugitive","subtype":"fire_suppression"},{"sourceId":"80000000-0000-4000-8000-000000001009","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000101","category":"stationary_combustion","subtype":"other_stationary_fuel"},{"sourceId":"80000000-0000-4000-8000-000000001010","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000102","category":"mobile_combustion","subtype":"on_road_vehicle"},{"sourceId":"80000000-0000-4000-8000-000000001011","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000102","category":"mobile_combustion","subtype":"non_road_equipment"},{"sourceId":"80000000-0000-4000-8000-000000001012","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000101","category":"process_emissions","subtype":"process_screen"},{"sourceId":"80000000-0000-4000-8000-000000001013","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000101","category":"direct_gas_release","subtype":"direct_gas"},{"sourceId":"80000000-0000-4000-8000-000000001014","entityId":"80000000-0000-4000-8000-000000000001","locationId":"80000000-0000-4000-8000-000000000102","category":"other_direct_scope1","subtype":"other_direct"}]'::jsonb;
  if (select jsonb_agg(jsonb_build_object('sourceId',x->'sourceId','entityId',x->'entityId','locationId',x->'locationId','category',x->'category','subtype',x->'subtype')order by x->>'sourceId' collate "C")from jsonb_array_elements(s->'sources')x)is distinct from expected_sources then raise exception 'fixture source identity mismatch' using errcode='22023';end if;
  for x in select value from jsonb_array_elements(s->'sources') loop perform neuvetra.m71_keys(x,'sourceId,entityId,locationId,category,subtype,knownFacts,processScreen,evidenceRequirementIds');perform neuvetra.m71_keys(x->'knownFacts','fuelOrGas,equipmentKind,activityDataKind,activityUnit');if coalesce(x#>>'{knownFacts,fuelOrGas}','')not in('fossil_natural_gas','fossil_distillate_no2','fossil_diesel','gasoline','propane_lpg','renewable_diesel','other_fuel','HFC-134a','HFC-227ea','R-410A','other_gas','not_applicable','unknown') or coalesce(x#>>'{knownFacts,equipmentKind}','')not in('stationary_other','emergency_generator','medium_heavy_on_road_2007_2022','vehicle_other','non_road_equipment','refrigeration','fixed_hvac','fire_suppression','industrial_process','other','unknown') or coalesce(x#>>'{knownFacts,activityDataKind}','')not in('annual_hhv_energy','metered_gallons','gallons_and_actual_miles','service_refill_mass','screen_only','unknown') or coalesce(x#>>'{knownFacts,activityUnit}','')not in('MMBtu_HHV','US_gallon','US_gallon_and_vehicle_mile','kg_named_gas_or_blend','not_applicable','unknown') or jsonb_typeof(x->'evidenceRequirementIds')is distinct from 'array' then raise exception 'invalid source facts' using errcode='22023';end if;if x->>'sourceId'='80000000-0000-4000-8000-000000001012' then if jsonb_typeof(x->'processScreen')is distinct from 'object' then raise exception 'process screen required' using errcode='22023';end if;perform neuvetra.m71_keys(x->'processScreen','categories,gasGroups');if jsonb_array_length(x#>'{processScreen,categories}')<>7 or jsonb_array_length(x#>'{processScreen,gasGroups}')<>7 or (select array_agg(c->>'category'order by c->>'category'collate "C")from jsonb_array_elements(x#>'{processScreen,categories}')c)is distinct from array['agricultural_biological','chemical_production','metal_production','mineral_products','oil_and_gas','other_direct_process','waste_treatment'] or (select array_agg(g->>'gasGroup'order by g->>'gasGroup'collate "C")from jsonb_array_elements(x#>'{processScreen,gasGroups}')g)is distinct from array['CH4','CO2','HFCs','N2O','NF3','PFCs','SF6'] then raise exception 'complete process screen required' using errcode='22023';end if;for y in select value from jsonb_array_elements(x#>'{processScreen,categories}') loop perform neuvetra.m71_keys(y,'category,state');if coalesce(y->>'state','')not in('unknown','indicated','not_applicable_pending_review')then raise exception 'invalid process state'using errcode='22023';end if;end loop;for y in select value from jsonb_array_elements(x#>'{processScreen,gasGroups}') loop perform neuvetra.m71_keys(y,'gasGroup,state');if coalesce(y->>'state','')not in('unknown','indicated','not_applicable_pending_review')then raise exception 'invalid gas state'using errcode='22023';end if;end loop;else if x->'processScreen'is distinct from 'null'::jsonb then raise exception 'unexpected process screen'using errcode='22023';end if;end if;end loop;
  expected_evidence:='[{"requirementId":"80000000-0000-4000-8000-000000002001","sourceId":"80000000-0000-4000-8000-000000001001","requirementType":"fuel_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-STATIONARY-GAS-01"},{"requirementId":"80000000-0000-4000-8000-000000002002","sourceId":"80000000-0000-4000-8000-000000001001","requirementType":"meter_summary","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-STATIONARY-GAS-02"},{"requirementId":"80000000-0000-4000-8000-000000002003","sourceId":"80000000-0000-4000-8000-000000001002","requirementType":"fuel_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-STATIONARY-DIESEL-01"},{"requirementId":"80000000-0000-4000-8000-000000002004","sourceId":"80000000-0000-4000-8000-000000001003","requirementType":"vehicle_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-MOBILE-DIESEL-01"},{"requirementId":"80000000-0000-4000-8000-000000002005","sourceId":"80000000-0000-4000-8000-000000001003","requirementType":"mileage_evidence","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-MOBILE-DIESEL-02"},{"requirementId":"80000000-0000-4000-8000-000000002006","sourceId":"80000000-0000-4000-8000-000000001004","requirementType":"equipment_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-HFC134A-01"},{"requirementId":"80000000-0000-4000-8000-000000002007","sourceId":"80000000-0000-4000-8000-000000001004","requirementType":"service_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-HFC134A-02"},{"requirementId":"80000000-0000-4000-8000-000000002008","sourceId":"80000000-0000-4000-8000-000000001005","requirementType":"equipment_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-R410A-01"},{"requirementId":"80000000-0000-4000-8000-000000002009","sourceId":"80000000-0000-4000-8000-000000001005","requirementType":"service_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-R410A-02"},{"requirementId":"80000000-0000-4000-8000-000000002010","sourceId":"80000000-0000-4000-8000-000000001006","requirementType":"equipment_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-HFC227EA-01"},{"requirementId":"80000000-0000-4000-8000-000000002011","sourceId":"80000000-0000-4000-8000-000000001006","requirementType":"service_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-HFC227EA-02"},{"requirementId":"80000000-0000-4000-8000-000000002012","sourceId":"80000000-0000-4000-8000-000000001007","requirementType":"equipment_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-OTHER-REFRIGERANT-01"},{"requirementId":"80000000-0000-4000-8000-000000002013","sourceId":"80000000-0000-4000-8000-000000001008","requirementType":"equipment_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-OTHER-FIRE-01"},{"requirementId":"80000000-0000-4000-8000-000000002014","sourceId":"80000000-0000-4000-8000-000000001009","requirementType":"fuel_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-OTHER-STATIONARY-01"},{"requirementId":"80000000-0000-4000-8000-000000002015","sourceId":"80000000-0000-4000-8000-000000001010","requirementType":"vehicle_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-GASOLINE-01"},{"requirementId":"80000000-0000-4000-8000-000000002016","sourceId":"80000000-0000-4000-8000-000000001011","requirementType":"equipment_register","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-NONROAD-01"},{"requirementId":"80000000-0000-4000-8000-000000002017","sourceId":"80000000-0000-4000-8000-000000001012","requirementType":"process_screen_attestation","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-PROCESS-01"},{"requirementId":"80000000-0000-4000-8000-000000002018","sourceId":"80000000-0000-4000-8000-000000001013","requirementType":"direct_release_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-DIRECT-GAS-01"},{"requirementId":"80000000-0000-4000-8000-000000002019","sourceId":"80000000-0000-4000-8000-000000001014","requirementType":"source_census_record","coveragePeriod":"calendar_2025_proposed","fixtureReferenceKey":"M80-EVIDENCE-UNCLASSIFIED-01"}]'::jsonb;
  for x in select value from jsonb_array_elements(s->'evidenceRequirements') loop perform neuvetra.m71_keys(x,'requirementId,sourceId,requirementType,coveragePeriod,state,fixtureReferenceKey');if coalesce(x->>'state','')not in('unknown','missing','synthetic_fixture_reference')then raise exception 'invalid evidence state'using errcode='22023';end if;end loop;
  if (select jsonb_agg(x-'state'order by x->>'requirementId'collate "C")from jsonb_array_elements(s->'evidenceRequirements')x)is distinct from expected_evidence or exists(select 1 from jsonb_array_elements(s->'sources')src,jsonb_array_elements_text(src->'evidenceRequirementIds')rid where not exists(select 1 from jsonb_array_elements(s->'evidenceRequirements')e where e->>'requirementId'=rid and e->>'sourceId'=src->>'sourceId')) or (select array_agg(rid order by rid collate "C")from jsonb_array_elements(s->'sources')src,jsonb_array_elements_text(src->'evidenceRequirementIds')rid)is distinct from(select array_agg(e->>'requirementId'order by e->>'requirementId'collate "C")from jsonb_array_elements(expected_evidence)e) then raise exception 'fixture evidence identity mismatch'using errcode='22023';end if;
end $$;
revoke all on function neuvetra.m80_assert_setup(uuid,jsonb) from public,authenticated,neuvetra_runtime;

create function neuvetra.save_scope1_beta_setup(target_company uuid,request jsonb,setup jsonb,version_payload jsonb) returns table(record_id uuid,replayed boolean) language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare actor uuid:=auth.uid();old neuvetra.scope1_beta_requests%rowtype;head neuvetra.scope1_beta_setup_heads%rowtype;fingerprint text;captured timestamptz;begin
  if actor is null or not neuvetra.has_staging_access() or not neuvetra.can_manage_company(target_company) then raise exception 'foundation not found'using errcode='42501';end if;
  perform neuvetra.m71_keys(request,'profile,idempotencyKey,expectedRevision,expectedVersionId,expectedVersionSha256,correctionReason');perform neuvetra.m71_keys(version_payload,'profile,id,companyId,reportingYear,revision,previousVersionId,previousVersionSha256,fixtureProfileId,fixtureVersion,fixtureSha256,payloadSha256,createdBy,createdAt,dataClassification,completeness,releasedSupportedCount,versionSha256');
  if jsonb_typeof(request->'profile')is distinct from 'string' or request->>'profile'is distinct from 'm80-scope1-beta-foundation-runtime-v1' or jsonb_typeof(request->'idempotencyKey')is distinct from 'string' or coalesce(request->>'idempotencyKey','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedRevision')is distinct from 'number' or coalesce(request->>'expectedRevision','')!~'^[0-9]+$' or jsonb_typeof(request->'expectedVersionId')not in('string','null') or jsonb_typeof(request->'expectedVersionSha256')not in('string','null') or jsonb_typeof(request->'correctionReason')not in('string','null') then raise exception 'invalid setup request'using errcode='22023';end if;
  if not exists(select 1 from neuvetra.scope1_beta_fixture_admissions where company_id=target_company and fixture_profile_id='m80-synthetic-scope1-foundation-v1'and fixture_version=1 and fixture_sha256='2c6a9f78cded2a209bf536969e4ea389baa7fe1633c8ef63fad0c22826f77dc1'and active)then raise exception 'foundation not found'using errcode='42501';end if;
  if (select count(*)from neuvetra.scope1_beta_release_records)<>4 or (select array_agg(profile_id order by profile_id collate "C")from neuvetra.scope1_beta_release_records)is distinct from array['controlled_on_road_fossil_diesel_medium_heavy_2007_2022','stable_serviced_fugitive_equipment','stationary_fossil_distillate_no2_emergency_generator_default_hhv','stationary_natural_gas_hhv_mmbtu'] or exists(select 1 from neuvetra.scope1_beta_release_records where status<>'held_candidate'or effective_at is not null or superseded_at is not null or reporting_period_start<>'2025-01-01'or reporting_period_end_exclusive<>'2026-01-01'or exclusions<>'["domain_release_pending","rights_release_pending","runtime_release_prohibited"]'::jsonb or decision_artifact_sha256<>'848883159be48c88a0dab8589ad371dcdbbf8dd07966a3d5fbcfd0799f7a530b'or method_sha256<>case profile_id when 'stationary_natural_gas_hhv_mmbtu'then'a596ea0d377f33ac34e1333852c313c855c2a18ac08006525a78bbfb7cce9898'when'controlled_on_road_fossil_diesel_medium_heavy_2007_2022'then'7598384902729e8a6708beb359e7564f500ad85c0d3ad38f094ee580a05c0497'when'stationary_fossil_distillate_no2_emergency_generator_default_hhv'then'8924b6c99a7b2b1525f2f2ef641978bbdfc5c7116c40a9fc828e418e56a4a722'when'stable_serviced_fugitive_equipment'then'acbfed90deaf7c164fe889b87732a998396ace265c92973ba3f79c6a71c038af'end) then raise exception 'release registry unavailable'using errcode='22023';end if;
  perform neuvetra.m80_assert_setup(target_company,setup);
  fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save_scope1_beta_setup','actor',actor,'companyId',target_company,'request',request-'idempotencyKey','setup',setup));
  select * into old from neuvetra.scope1_beta_requests r where r.company_id=target_company and r.idempotency_key=(request->>'idempotencyKey')::uuid;
  if found then if old.actor_id<>actor or old.request_sha256<>fingerprint then raise exception 'idempotency conflict'using errcode='23505';end if;record_id:=old.record_id;replayed:=true;return next;return;end if;
  perform id from neuvetra.companies where id=target_company for update;
  select * into head from neuvetra.scope1_beta_setup_heads h where h.company_id=target_company and h.reporting_year=2025 for update;
  if coalesce(head.revision,0)<>(request->>'expectedRevision')::integer or request->'expectedVersionId'is distinct from coalesce(to_jsonb(head.version_id::text),'null'::jsonb) or (head.version_id is not null and request->>'expectedVersionSha256'is distinct from(select v.version_sha256 from neuvetra.scope1_beta_setup_versions v where v.company_id=target_company and v.id=head.version_id)) or (head.version_id is null and request->'expectedVersionSha256'<>'null'::jsonb) then raise exception 'setup predecessor changed'using errcode='23505';end if;
  if jsonb_typeof(version_payload->'createdAt')is distinct from 'string' or coalesce(version_payload->>'createdAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' then raise exception 'setup semantic integrity'using errcode='22023';end if;
  captured:=(version_payload->>'createdAt')::timestamptz;
  if jsonb_typeof(version_payload->'profile')is distinct from 'string' or jsonb_typeof(version_payload->'id')is distinct from 'string' or jsonb_typeof(version_payload->'companyId')is distinct from 'string' or jsonb_typeof(version_payload->'reportingYear')is distinct from 'number' or jsonb_typeof(version_payload->'revision')is distinct from 'number' or jsonb_typeof(version_payload->'previousVersionId')not in('string','null') or jsonb_typeof(version_payload->'previousVersionSha256')not in('string','null') or jsonb_typeof(version_payload->'fixtureProfileId')is distinct from 'string' or jsonb_typeof(version_payload->'fixtureVersion')is distinct from 'number' or jsonb_typeof(version_payload->'fixtureSha256')is distinct from 'string' or jsonb_typeof(version_payload->'payloadSha256')is distinct from 'string' or jsonb_typeof(version_payload->'createdBy')is distinct from 'string' or jsonb_typeof(version_payload->'dataClassification')is distinct from 'string' or jsonb_typeof(version_payload->'completeness')is distinct from 'string' or jsonb_typeof(version_payload->'releasedSupportedCount')is distinct from 'number' or jsonb_typeof(version_payload->'versionSha256')is distinct from 'string' or version_payload->>'profile'is distinct from 'm80-scope1-beta-foundation-runtime-v1' or version_payload->>'companyId'is distinct from target_company::text or version_payload->>'reportingYear'is distinct from '2025' or coalesce(version_payload->>'revision','')!~'^[0-9]+$' or (version_payload->>'revision')::integer<>coalesce(head.revision,0)+1 or version_payload->'previousVersionId'is distinct from request->'expectedVersionId' or version_payload->'previousVersionSha256'is distinct from request->'expectedVersionSha256' or version_payload->>'fixtureProfileId'is distinct from 'm80-synthetic-scope1-foundation-v1' or version_payload->>'fixtureVersion'is distinct from '1' or version_payload->>'fixtureSha256'is distinct from '2c6a9f78cded2a209bf536969e4ea389baa7fe1633c8ef63fad0c22826f77dc1' or version_payload->>'payloadSha256'is distinct from neuvetra.m67_hash(setup) or version_payload->>'createdBy'is distinct from actor::text or to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')is distinct from version_payload->>'createdAt' or abs(extract(epoch from(clock_timestamp()-captured)))>120 or version_payload->>'dataClassification'is distinct from 'synthetic_rehearsal' or version_payload->>'completeness'is distinct from 'incomplete' or version_payload->>'releasedSupportedCount'is distinct from '0' or version_payload->>'versionSha256'is distinct from neuvetra.m67_hash(version_payload-'versionSha256') or (coalesce(head.revision,0)=0 and request->'correctionReason'is distinct from 'null'::jsonb) or (coalesce(head.revision,0)>0 and request->>'correctionReason'is distinct from 'synthetic_fact_correction') then raise exception 'setup semantic integrity'using errcode='22023';end if;
  if (select count(*)from neuvetra.scope1_beta_setup_versions where company_id=target_company)>=100 or (select coalesce(sum(octet_length(convert_to(canonical_payload,'utf8'))),0)from neuvetra.scope1_beta_setup_versions where company_id=target_company)+octet_length(convert_to(neuvetra.m67_canonical(setup),'utf8'))>5000000 then raise exception 'setup history capacity reached'using errcode='54000';end if;
  insert into neuvetra.scope1_beta_setup_versions(id,company_id,reporting_year,revision,previous_version_id,previous_version_sha256,fixture_profile_id,fixture_version,fixture_sha256,payload,canonical_payload,payload_sha256,version_sha256,created_by,created_at,correction_reason,data_classification,completeness,released_supported_count) values((version_payload->>'id')::uuid,target_company,2025,(version_payload->>'revision')::integer,nullif(version_payload->>'previousVersionId','')::uuid,version_payload->>'previousVersionSha256','m80-synthetic-scope1-foundation-v1',1,'2c6a9f78cded2a209bf536969e4ea389baa7fe1633c8ef63fad0c22826f77dc1',setup,neuvetra.m67_canonical(setup),version_payload->>'payloadSha256',version_payload->>'versionSha256',actor,captured,request->>'correctionReason','synthetic_rehearsal','incomplete',0);
  insert into neuvetra.scope1_beta_setup_heads(company_id,reporting_year,version_id,revision)values(target_company,2025,(version_payload->>'id')::uuid,(version_payload->>'revision')::integer)on conflict(company_id,reporting_year)do update set version_id=excluded.version_id,revision=excluded.revision;
  insert into neuvetra.scope1_beta_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,fingerprint,(version_payload->>'id')::uuid,captured);
  insert into neuvetra.scope1_beta_audit(id,company_id,record_id,event_type,record_sha256,actor_id,created_at)values(gen_random_uuid(),target_company,(version_payload->>'id')::uuid,'setup_saved',version_payload->>'versionSha256',actor,captured);
  record_id:=(version_payload->>'id')::uuid;replayed:=false;return next;
end $$;
revoke all on function neuvetra.save_scope1_beta_setup(uuid,jsonb,jsonb,jsonb) from public,authenticated,neuvetra_runtime;
grant execute on function neuvetra.save_scope1_beta_setup(uuid,jsonb,jsonb,jsonb) to neuvetra_runtime;
